-- Kalekim: данные 3 товаров с kalekim.com (5110 Performa+, 4201 Mastar 10, 5510 İnce Akrilik Macun)
-- Безопасно: ДОБАВЛЯЕТ поля (описание, применение, характеристики, документы) и не трогает цены, фасовки, фото.
-- Запустить в Supabase: SQL Editor > New query > вставить > Run (на красное предупреждение ответить Run).

update products set extra = coalesce(extra, '{}'::jsonb) || $j${"d":"Особо эластичная водная фасадная краска на основе акриловой эмульсии, матовая. Образует эластичное покрытие, которое перекрывает волосяные трещины, выдерживает движения здания и сохраняет эластичность при низких температурах. Водонепроницаема: защищает от дождя, предотвращает кристаллизацию солей, морозные трещины, рост водорослей и грибка. Долговечна: устойчива к УФ-лучам, дождю, жаре и морозу. Паропроницаема, хорошо укрывает, не содержит растворителей и почти не пахнет, разбавляется водой.","d_ka":"ექსტრა ელასტიკური, წყალზე დამზადებული ფასადის მქრქალი საღებავი აკრილის ემულსიის საფუძველზე. ქმნის ელასტიკურ ფენას, რომელიც ფარავს თმისებრ ბზარებს, უძლებს შენობის მოძრაობას და დაბალ ტემპერატურაზეც ინარჩუნებს ელასტიკურობას. წყალგაუმტარია: იცავს წვიმისგან და ხელს უშლის მარილების კრისტალიზაციას, ყინვისგან გაბზარვას, წყალმცენარეებისა და სოკოს გაჩენას. გამძლეა ულტრაიისფერი სხივების, წვიმის, სიცხისა და ყინვის მიმართ. ორთქლგამტარია, კარგად ფარავს, არ შეიცავს გამხსნელს, თითქმის უსუნოა და წყლით განზავდება.","d_en":"Extra-elastic, water-based, matt exterior paint on an acrylic emulsion base. It forms an elastic film that covers hairline cracks, follows the movement of the building and stays elastic at low temperatures. Waterproof: protects against rain and prevents salt crystallization, frost cracks, algae and fungus. Long-lasting: resistant to UV, rain, heat and frost. Breathable (high water-vapour permeability), good hiding power, solvent-free and almost odourless; thinned with water.","us":"Фасады: минеральные основания (бетон, раствор, цементные плиты) и ранее окрашенные поверхности.","us_ka":"ფასადები: მინერალური ზედაპირები (ბეტონი, ხსნარი, ცემენტის პანელები) და ადრე შეღებილი ზედაპირები.","us_en":"Facades: mineral surfaces (concrete, mortar, cement panels) and previously painted surfaces.","ext":true,"sp":[{"k":"Основа","v":"Акриловая эмульсия, разбавитель — вода","k_ka":"საფუძველი","v_ka":"აკრილის ემულსია, გამხსნელი — წყალი","k_en":"Binder","v_en":"Acrylic emulsion, thinner: water"},{"k":"Плотность","v":"≈ 1,39 г/см³","k_ka":"სიმკვრივე","v_ka":"≈ 1,39 გ/სმ³","k_en":"Density","v_en":"≈ 1.39 g/cm³"},{"k":"Упаковка","v":"Вёдра 2,5 л и 15 л","k_ka":"შეფუთვა","v_ka":"2,5 ლ და 15 ლ ვედროები","k_en":"Packaging","v_en":"2.5 L and 15 L pails"},{"k":"Расход","v":"0,12–0,13 л/м² на слой","k_ka":"ხარჯი","v_ka":"0,12–0,13 ლ/მ² თითო ფენაზე","k_en":"Consumption","v_en":"0.12–0.13 L/m² per coat"},{"k":"Температура нанесения","v":"+5…+35 °C","k_ka":"გამოყენების ტემპერატურა","v_ka":"+5…+35 °C","k_en":"Application temperature","v_en":"+5…+35 °C"},{"k":"Высыхание","v":"Повторное окрашивание через 6 ч, полностью высыхает за 24 ч","k_ka":"გაშრობა","v_ka":"გადაღებვა 6 საათის შემდეგ, სრულად შრება 24 საათში","k_en":"Drying","v_en":"Recoat after 6 h, fully dry in 24 h"},{"k":"Инструмент","v":"Кисть, валик, безвоздушное распыление","k_ka":"ინსტრუმენტი","v_ka":"ფუნჯი, როლიკი, უჰაერო შესხურება","k_en":"Tools","v_en":"Brush, roller, airless spray"},{"k":"Цвет","v":"Белая и колеровка по системе Kalekim (базы A, B, C)","k_ka":"ფერი","v_ka":"თეთრი და შეფერვა Kalekim-ის სისტემით (ბაზები A, B, C)","k_en":"Colour","v_en":"White and tinting with the Kalekim system (bases A, B, C)"},{"k":"Классификация EN 1062-1","v":"G3 · E2 · S1 · V2 · W3 · A2 · C0","k_ka":"კლასიფიკაცია EN 1062-1","v_ka":"G3 · E2 · S1 · V2 · W3 · A2 · C0","k_en":"Classification EN 1062-1","v_en":"G3 · E2 · S1 · V2 · W3 · A2 · C0"}],"docs":[{"t":"TDS (EN)","u":"https://cdn.kalekim.com//file/0/0/doc/8bbc9c23-e93a-4ec9-827f-ed971c60e8d6"},{"t":"TDS (RU)","u":"https://cdn.kalekim.com//file/0/0/doc/ab5856a5-307e-4cbe-adda-fe1a3d5fb5e6"},{"t":"Kalekim.com","u":"https://www.kalekim.com/tr-en/performa-plus"}],"src":"https://www.kalekim.com/tr-en/performa-plus"}$j$::jsonb where pid = 1;
update products set extra = coalesce(extra, '{}'::jsonb) || $j${"d":"Самовыравнивающаяся цементная смесь для внутренних полов: сглаживает перепады толщины от 2,5 до 10 мм на новых и существующих основаниях, где требуется высокая стойкость к нагрузкам. Отлично растекается, имеет высокую адгезию, наносится слоем до 10 мм без усадки, трещин и сетки микротрещин, набирает очень высокую прочность на сжатие и изгиб и устойчива к истиранию.","d_ka":"თვითგასწორებადი ცემენტის ნარევი შიდა იატაკებისთვის: ასწორებს სისქის სხვაობას 2,5-დან 10 მმ-მდე ახალ და არსებულ ზედაპირებზე, სადაც საჭიროა დიდი დატვირთვისადმი გამძლეობა. შესანიშნავად იფენება, აქვს მაღალი ადჰეზია, თითო ფენად 10 მმ-მდე წაისმება შეკუმშვის, ბზარებისა და მიკრობზარების გარეშე, სწრაფად იძენს მაღალ სიმტკიცეს კუმშვასა და ღუნვაზე და მდგრადია ცვეთის მიმართ.","d_en":"Self-levelling cement-based compound for interior floors: smooths thickness differences from 2.5 to 10 mm on new and existing substrates where high load resistance is needed. Spreads perfectly, has high adhesion, can be applied up to 10 mm per layer without shrinkage or cracking, develops very high compressive and flexural strength and resists abrasion.","us":"Выравнивание бетонных плит и цементных стяжек под дерево, ламинат, паркет, ковролин, ПВХ, линолеум и плитку; выравнивание существующих бетонных, терраццо, керамических и каменных полов; полы с высокой нагрузкой и интенсивным движением (склады) — против пыления и износа.","us_ka":"ბეტონის ფილებისა და ცემენტის ბადის გასწორება ხის, ლამინატის, პარკეტის, ხალიჩის, PVC-ის, ლინოლეუმისა და ფილის დასაგებად; არსებული ბეტონის, ტერაცოს, კერამიკისა და ბუნებრივი ქვის იატაკების გასწორება; დიდი დატვირთვისა და ინტენსიური მოძრაობის იატაკები (საწყობები) მტვერვისა და ცვეთისგან დასაცავად.","us_en":"Levelling concrete slabs and cement screeds under wood, laminate, parquet, carpet, PVC, linoleum and tile; levelling existing concrete, terrazzo, ceramic and natural stone floors; heavily loaded floors with intense traffic (warehouses) against dusting and abrasion.","sp":[{"k":"Внешний вид","v":"Серый порошок","k_ka":"გარეგნობა","v_ka":"რუხი ფხვნილი","k_en":"Appearance","v_en":"Grey powder"},{"k":"Упаковка","v":"Бумажные мешки 25 кг","k_ka":"შეფუთვა","v_ka":"25 კგ-იანი ქაღალდის ტომრები","k_en":"Packaging","v_en":"25 kg paper bags"},{"k":"Толщина слоя","v":"2,5–10 мм за один слой","k_ka":"ფენის სისქე","v_ka":"2,5–10 მმ ერთ ფენად","k_en":"Layer thickness","v_en":"2.5–10 mm per layer"},{"k":"Расход","v":"≈ 1,61 кг/м² на 1 мм толщины","k_ka":"ხარჯი","v_ka":"≈ 1,61 კგ/მ² 1 მმ სისქეზე","k_en":"Consumption","v_en":"≈ 1.61 kg/m² per 1 mm thickness"},{"k":"Затворение","v":"4,75–5,25 л воды на 25 кг порошка","k_ka":"გაზავება","v_ka":"4,75–5,25 ლ წყალი 25 კგ ფხვნილზე","k_en":"Mixing ratio","v_en":"4.75–5.25 L water per 25 kg powder"},{"k":"Жизнеспособность","v":"20 минут","k_ka":"გამოყენების დრო ხსნარისთვის","v_ka":"20 წუთი","k_en":"Pot life","v_en":"20 minutes"},{"k":"Готовность","v":"8 ч — лёгкая нагрузка, 24 ч — до укладки покрытия, 48 ч — полный набор прочности","k_ka":"მზადყოფნა","v_ka":"8 სთ — მსუბუქი დატვირთვა, 24 სთ — საფარის დაგებამდე, 48 სთ — სრული გამყარება","k_en":"Ready for use","v_en":"8 h light traffic, 24 h before bonding, 48 h full cure"},{"k":"Температура нанесения","v":"+5…+35 °C","k_ka":"გამოყენების ტემპერატურა","v_ka":"+5…+35 °C","k_en":"Application temperature","v_en":"+5…+35 °C"},{"k":"Прочность на сжатие","v":"≥ 20 Н/мм² (28 суток) — C20","k_ka":"კუმშვის სიმტკიცე","v_ka":"≥ 20 ნ/მმ² (28 დღე) — C20","k_en":"Compressive strength","v_en":"≥ 20 N/mm² (28 days) — C20"},{"k":"Прочность на изгиб","v":"≥ 4 Н/мм² (28 суток) — F4","k_ka":"ღუნვის სიმტკიცე","v_ka":"≥ 4 ნ/მმ² (28 დღე) — F4","k_en":"Flexural strength","v_en":"≥ 4 N/mm² (28 days) — F4"},{"k":"Износостойкость (Бёме)","v":"≤ 20 см³/50 см² — A22","k_ka":"ცვეთამედეგობა (ბემე)","v_ka":"≤ 20 სმ³/50 სმ² — A22","k_en":"Abrasion resistance (Böhme)","v_en":"≤ 20 cm³/50 cm² — A22"},{"k":"Рабочая температура","v":"−30…+80 °C","k_ka":"ექსპლუატაციის ტემპერატურა","v_ka":"−30…+80 °C","k_en":"Service temperature","v_en":"−30…+80 °C"},{"k":"Реакция на огонь","v":"A1","k_ka":"ცეცხლზე რეაქცია","v_ka":"A1","k_en":"Reaction to fire","v_en":"A1"},{"k":"Стандарт","v":"TS EN 13813","k_ka":"სტანდარტი","v_ka":"TS EN 13813","k_en":"Standard","v_en":"TS EN 13813"},{"k":"Срок хранения","v":"12 месяцев в сухом месте в закрытой упаковке","k_ka":"შენახვის ვადა","v_ka":"12 თვე მშრალ ადგილას დახურულ შეფუთვაში","k_en":"Shelf life","v_en":"12 months, sealed, dry place"}],"docs":[{"t":"TDS (EN)","u":"https://cdn.kalekim.com//file/0/0/doc/189232a1-3192-427c-99c0-f0bf3d9e8039"},{"t":"TDS (RU)","u":"https://cdn.kalekim.com//file/0/0/doc/d2b1a54a-61b1-4455-8d5a-4048cd272b02"},{"t":"SDS (EN)","u":"https://cdn.kalekim.com//file/0/0/doc/a1116a15-b1a6-4f9f-b160-ece9f0becaf5"},{"t":"Kalekim.com","u":"https://www.kalekim.com/dz-en/4201-mastar-10"}],"src":"https://www.kalekim.com/dz-en/4201-mastar-10"}$j$::jsonb where pid = 16;
update products set extra = coalesce(extra, '{}'::jsonb) || $j${"d":"Водная тонкая шпатлёвка на основе акрилового сополимера для выравнивания поверхностей. Формирует прочную гладкую поверхность без пыления, устойчива к влаге и не мешает паропроницаемости стены, снижает расход краски за счёт уменьшения пористости основания. Готова к применению, обладает высокой заполняющей способностью: ровная поверхность получается максимум за два слоя. Легко шлифуется, на водной основе, экологична.","d_ka":"წყლის საფუძველზე დამზადებული წვრილი აკრილის გასაშპაკლებელი მასა აკრილის კოპოლიმერის ემულსიაზე, ზედაპირის გასასწორებლად. ქმნის მტკიცე, გლუვ, არამტვრევად ზედაპირს, მდგრადია ტენის მიმართ და ხელს არ უშლის კედლის ორთქლგამტარობას, ამცირებს საღებავის ხარჯს ფორიანობის შემცირებით. მზადაა გამოსაყენებლად, აქვს მაღალი შემავსებელი უნარი: გლუვი ზედაპირი მაქსიმუმ ორ ფენაში მიიღება. ადვილად იხეხება, წყლის საფუძველზეა და ეკოლოგიურად უსაფრთხოა.","d_en":"Water-based fine surface-smoothing putty on an acrylic copolymer emulsion. It forms a strong, smooth, non-dusting surface, is moisture resistant and does not block the water-vapour permeability of the wall, and reduces paint consumption by reducing surface porosity. Ready to use, with high filling capacity: a smooth surface in two coats at most. Easy to sand, water-based and ecologically compatible.","us":"Выравнивание шероховатых бетонных и оштукатуренных поверхностей, заделка волосяных трещин, устранение дефектов после удаления вздувшегося старого покрытия.","us_ka":"ბეტონისა და მოლესილი უხეში ზედაპირების გასწორება, თმისებრი ბზარების შევსება, ბუშტუკოვანი ძველი საფარის მოცილების შემდეგ დარჩენილი ხარვეზების გასწორება.","us_en":"Smoothing rough concrete and plastered surfaces, filling hairline cracks and covering defects left after removing blistered old coating.","int":true,"sp":[{"k":"Цвет","v":"Белый с оттенком (off-white)","k_ka":"ფერი","v_ka":"მოთეთრო (off-white)","k_en":"Colour","v_en":"Off-white"},{"k":"Основа","v":"Акриловая эмульсия","k_ka":"საფუძველი","v_ka":"აკრილის ემულსია","k_en":"Binder","v_en":"Acrylic emulsion"},{"k":"Упаковка","v":"Вёдра 5 кг и 25 кг (5 кг — по 2 шт. в упаковке)","k_ka":"შეფუთვა","v_ka":"5 კგ და 25 კგ ვედროები (5 კგ — წყვილად შეფუთული)","k_en":"Packaging","v_en":"5 kg and 25 kg pails (5 kg packed in 2s)"},{"k":"Расход","v":"0,5–1,5 кг/м² (зависит от ровности и пористости основания)","k_ka":"ხარჯი","v_ka":"0,5–1,5 კგ/მ² (დამოკიდებულია ზედაპირის სიგლუვესა და ფორიანობაზე)","k_en":"Consumption","v_en":"0.5–1.5 kg/m² (depends on evenness and porosity)"},{"k":"Температура нанесения","v":"+5…+35 °C","k_ka":"გამოყენების ტემპერატურა","v_ka":"+5…+35 °C","k_en":"Application temperature","v_en":"+5…+35 °C"},{"k":"Высыхание","v":"Полностью высыхает за 24 ч (при низкой температуре и высокой влажности — дольше)","k_ka":"გაშრობა","v_ka":"სრულად შრება 24 საათში (დაბალ ტემპერატურასა და მაღალ ტენიანობაზე უფრო დიდხანს)","k_en":"Drying","v_en":"Fully dry after 24 h (longer at low temperature / high humidity)"},{"k":"Инструмент","v":"Шпатель, гибкий шпатель из нержавеющей стали","k_ka":"ინსტრუმენტი","v_ka":"სპატულა, მოქნილი უჟანგავი ფოლადის სპატულა","k_en":"Tools","v_en":"Spatula, flexible stainless-steel trowel"},{"k":"Рабочая температура","v":"−30…+80 °C","k_ka":"ექსპლუატაციის ტემპერატურა","v_ka":"−30…+80 °C","k_en":"Service temperature","v_en":"−30…+80 °C"}],"docs":[{"t":"TDS (EN)","u":"https://cdn.kalekim.com//file/0/0/doc/bff1ae11-0f19-4719-b3a9-8c2e9f9f30ac"},{"t":"TDS (RU)","u":"https://cdn.kalekim.com//file/0/0/doc/5932219a-721d-4e4c-b877-f154903c6c90"},{"t":"SDS (EN)","u":"https://cdn.kalekim.com//file/0/0/doc/e012288b-5d7a-4a33-921d-8427bd3aa8ed"},{"t":"Kalekim.com","u":"https://www.kalekim.com/fr-en/ince-akrilik-macun"}],"src":"https://www.kalekim.com/fr-en/ince-akrilik-macun"}$j$::jsonb where pid = 17;

-- Проверка (должно вернуть 3 строки):
select pid, name, jsonb_array_length(extra->'sp') as spec_rows, jsonb_array_length(extra->'docs') as docs from products where pid in (1,16,17) order by pid;
